import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './CSS/Products.css';

const Products = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [selectedCategory, setSelectedCategory] = useState('All');
  
  // State for opening the product detail modal
  const [selectedProduct, setSelectedProduct] = useState(null);
  // State for active image inside the modal preview
  const [activeModalImage, setActiveModalImage] = useState('');
  // State for item quantity in modal
  const [quantity, setQuantity] = useState(1);

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      setLoading(true);
      const response = await axios.get('http://localhost:4000/api/seller/products');
      
      if (Array.isArray(response.data)) {
        setProducts(response.data);
      } else if (response.data && Array.isArray(response.data.products)) {
        setProducts(response.data.products);
      } else {
        setProducts([]);
      }
    } catch (err) {
      console.error('Error fetching products:', err);
      setProducts([]);
    } finally {
      setLoading(false);
    }
  };

  const filteredProducts = products.filter((product) => {
    if (selectedCategory === 'All') return true;
    return product.category?.toLowerCase() === selectedCategory.toLowerCase();
  });

  const categories = ['All', 'Electronics', 'Fashion', 'Home & Kitchen', 'Furnitures'];

  // Helper function to resolve image URLs correctly
  const resolveImageSrc = (rawImage) => {
    if (!rawImage) return 'https://via.placeholder.com/200';
    const cleanPath = String(rawImage).replace(/\\/g, '/');

    if (cleanPath.startsWith('http://') || cleanPath.startsWith('https://')) {
      return cleanPath;
    } else if (cleanPath.startsWith('/uploads')) {
      return `http://localhost:4000${cleanPath}`;
    } else if (cleanPath.startsWith('uploads')) {
      return `http://localhost:4000/${cleanPath}`;
    } else {
      return `http://localhost:4000/uploads/${cleanPath}`;
    }
  };

  // Handler to open modal and set the primary image
  const handleOpenModal = (item) => {
    setSelectedProduct(item);
    setQuantity(1);

    // BACKEND ADD TO CART FUNCTION
  const handleAddToCart = async (product, itemQty = 1, e) => {
    if (e) e.stopPropagation(); // Prevents modal from toggling if clicked on card

    const cartItem = {
      _id: product._id || product.id,
      title: product.title || product.name,
      price: Number(product.price),
      image: resolveImageSrc(product.images?.[0] || product.imageUrl || product.image),
      category: product.category,
      quantity: itemQty
    };

    try {
      const response = await fetch('http://localhost:4000/api/cart/add', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          userId: 'guest_user', // Change to dynamic user ID if authentication is implemented
          product: cartItem
        }),
      });

      const data = await response.json();
      if (response.ok) {
        alert('Product added to cart successfully!');
        
        // Close modal if open
        if (selectedProduct) {
          setSelectedProduct(null);
        }
      } else {
        alert('Failed to add product: ' + (data.error || 'Unknown error'));
      }
    } catch (err) {
      console.error('Error adding to cart:', err);
      alert('Network error while adding to cart.');
    }
  };
    
    let firstImg = 'https://via.placeholder.com/200';
    if (item.images && item.images.length > 0) {
      firstImg = item.images[0];
    } else if (item.imageUrl || item.image) {
      firstImg = item.imageUrl || item.image;
    }
    setActiveModalImage(resolveImageSrc(firstImg));
  };

  // ADD TO CART FUNCTION
  const handleAddToCart = (product, itemQty = 1, e) => {
    if (e) e.stopPropagation(); // Prevents modal from toggling if clicked on card

    const cartItem = {
      _id: product._id || product.id,
      title: product.title || product.name,
      price: Number(product.price),
      image: resolveImageSrc(product.images?.[0] || product.imageUrl || product.image),
      category: product.category,
      quantity: itemQty
    };

    // 1. Fetch current cart from LocalStorage
    const existingCart = JSON.parse(localStorage.getItem('cartItems')) || [];

    // 2. Check if product already exists in cart
    const existingIndex = existingCart.findIndex(
      (item) => item._id === cartItem._id
    );

    if (existingIndex > -1) {
      existingCart[existingIndex].quantity += itemQty;
    } else {
      existingCart.push(cartItem);
    }

    // 3. Save updated list back to LocalStorage
    localStorage.setItem('cartItems', JSON.stringify(existingCart));

    // 4. Dispatch custom event so Cart / Navbar components re-render immediately
    window.dispatchEvent(new Event('cartUpdated'));

    alert(`${cartItem.title} added to cart!`);
    
    // Close modal if open
    if (selectedProduct) {
      setSelectedProduct(null);
    }
  };

  return (
    <div className="products-container">
      <div className="products-hero">
        <h1>Explore All Products</h1>
        <p>Discover top-tier mobile devices, wearables, and high-performance tech accessories.</p>

        <div className="category-tabs">
          {categories.map((cat) => (
            <button
              key={cat}
              className={`category-btn ${selectedCategory === cat ? 'active' : ''}`}
              onClick={() => setSelectedCategory(cat)}
            >
              {cat}
            </button>
          ))}
        </div>
      </div>

      <div className="products-grid-wrapper">
        {loading ? (
          <p>Loading products from database...</p>
        ) : filteredProducts.length === 0 ? (
          <p>No products available in this category.</p>
        ) : (
          <div className="products-grid">
            {filteredProducts.map((item) => {
              let rawImage = item.images && item.images.length > 0 ? item.images[0] : item.imageUrl || item.image;
              let imageSrc = resolveImageSrc(rawImage);

              return (
                <div 
                  key={item._id || item.id} 
                  className="product-card"
                  onClick={() => handleOpenModal(item)}
                  style={{ cursor: 'pointer' }}
                >
                  <div className="image-box">
                    <img 
                      src={imageSrc} 
                      alt={item.title || item.name} 
                      onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }}
                    />
                  </div>
                  <div className="card-details">
                    <span className="card-category">{item.category}</span>
                    <h3 className="card-title">{item.title || item.name}</h3>
                    <div className="card-footer">
                      <span>★ 4.5</span>
                      <strong>${item.price}</strong>
                    </div>

                    <button 
            onClick={(e) => {
              e.stopPropagation(); // Prevents modal from opening when clicking the button
              handleAddToCart(item);
            }} 
            className="add-to-cart-btn"
          >
            Add to Cart
          </button>

                    <button
                      onClick={(e) => handleAddToCart(item, 1, e)}
                      style={{
                        marginTop: '12px',
                        width: '100%',
                        padding: '8px 12px',
                        backgroundColor: '#4f46e5',
                        color: '#fff',
                        border: 'none',
                        borderRadius: '6px',
                        fontWeight: '600',
                        cursor: 'pointer'
                      }}
                    >
                      Add to Cart
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* PRODUCT DETAILS MODAL */}
      {selectedProduct && (
        <div 
          className="product-modal-backdrop"
          onClick={() => setSelectedProduct(null)}
          style={{
            position: 'fixed',
            top: 0,
            left: 0,
            width: '100vw',
            height: '100vh',
            backgroundColor: 'rgba(0, 0, 0, 0.65)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 1000,
            padding: '20px'
          }}
        >
          <div 
            className="product-modal-card"
            onClick={(e) => e.stopPropagation()}
            style={{
              backgroundColor: '#fff',
              borderRadius: '16px',
              maxWidth: '800px',
              width: '100%',
              maxHeight: '90vh',
              overflowY: 'auto',
              padding: '30px',
              position: 'relative',
              boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1)'
            }}
          >
            {/* CLOSE BUTTON */}
            <button 
              onClick={() => setSelectedProduct(null)}
              style={{
                position: 'absolute',
                top: '16px',
                right: '20px',
                background: '#f3f4f6',
                border: 'none',
                borderRadius: '50%',
                width: '36px',
                height: '36px',
                fontSize: '20px',
                fontWeight: 'bold',
                cursor: 'pointer',
                color: '#374151'
              }}
            >
              &times;
            </button>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px', marginTop: '10px' }}>
              
              {/* LEFT COLUMN: IMAGES */}
              <div>
                <div style={{
                  width: '100%',
                  height: '280px',
                  borderRadius: '12px',
                  overflow: 'hidden',
                  border: '1px solid #e5e7eb',
                  marginBottom: '12px'
                }}>
                  <img 
                    src={activeModalImage} 
                    alt={selectedProduct.title || selectedProduct.name}
                    style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                    onError={(e) => { e.target.src = 'https://via.placeholder.com/200'; }}
                  />
                </div>

                {/* THUMBNAILS LIST */}
                {selectedProduct.images && selectedProduct.images.length > 1 && (
                  <div style={{ display: 'flex', gap: '8px', overflowX: 'auto', paddingBottom: '4px' }}>
                    {selectedProduct.images.map((img, idx) => {
                      const fullSrc = resolveImageSrc(img);
                      return (
                        <img 
                          key={idx}
                          src={fullSrc}
                          alt={`Thumbnail ${idx}`}
                          onClick={() => setActiveModalImage(fullSrc)}
                          style={{
                            width: '50px',
                            height: '50px',
                            borderRadius: '6px',
                            objectFit: 'cover',
                            cursor: 'pointer',
                            border: activeModalImage === fullSrc ? '2px solid #4f46e5' : '1px solid #e5e7eb'
                          }}
                        />
                      );
                    })}
                  </div>
                )}
              </div>

              {/* RIGHT COLUMN: DETAILS */}
              <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
                <div>
                  <span style={{ fontSize: '12px', textTransform: 'uppercase', color: '#6b7280', fontWeight: 'bold' }}>
                    {selectedProduct.category} {selectedProduct.brand ? `• ${selectedProduct.brand}` : ''}
                  </span>
                  <h2 style={{ fontSize: '22px', color: '#111827', margin: '4px 0' }}>
                    {selectedProduct.title || selectedProduct.name}
                  </h2>
                </div>

                <div style={{ display: 'flex', alignItems: 'baseline', gap: '12px' }}>
                  <span style={{ fontSize: '24px', fontWeight: 'bold', color: '#111827' }}>
                    ${selectedProduct.price}
                  </span>
                  {selectedProduct.mrp && (
                    <span style={{ fontSize: '16px', color: '#9ca3af', textDecoration: 'line-through' }}>
                      ${selectedProduct.mrp}
                    </span>
                  )}
                </div>

                {/* QUANTITY PICKER & ADD TO CART BUTTON */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '12px', margin: '10px 0' }}>
                  <div style={{ display: 'flex', alignItems: 'center', border: '1px solid #d1d5db', borderRadius: '6px' }}>
                    <button 
                      onClick={() => setQuantity(prev => Math.max(1, prev - 1))}
                      style={{ padding: '6px 12px', border: 'none', background: 'transparent', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                      -
                    </button>
                    <span style={{ padding: '0 10px', fontWeight: 'bold' }}>{quantity}</span>
                    <button 
                      onClick={() => setQuantity(prev => prev + 1)}
                      style={{ padding: '6px 12px', border: 'none', background: 'transparent', cursor: 'pointer', fontWeight: 'bold' }}
                    >
                      +
                    </button>
                  </div>

                  <button
                    onClick={() => handleAddToCart(selectedProduct, quantity)}
                    style={{
                      flex: 1,
                      padding: '10px 16px',
                      backgroundColor: '#4f46e5',
                      color: '#fff',
                      border: 'none',
                      borderRadius: '6px',
                      fontWeight: 'bold',
                      cursor: 'pointer'
                    }}
                  >
                    Add to Cart
                  </button>
                </div>

                {/* DESCRIPTION */}
                <div style={{ borderTop: '1px solid #f3f4f6', paddingTop: '12px' }}>
                  <h4 style={{ fontSize: '14px', fontWeight: 'bold', color: '#374151', marginBottom: '6px' }}>
                    Product Description
                  </h4>
                  <p style={{ fontSize: '14px', color: '#4b5563', lineHeight: '1.5', margin: 0 }}>
                    {selectedProduct.description || 'No detailed description available.'}
                  </p>
                </div>

                {/* KEY FEATURES */}
                {selectedProduct.features && (
                  <div style={{ borderTop: '1px solid #f3f4f6', paddingTop: '12px' }}>
                    <h4 style={{ fontSize: '14px', fontWeight: 'bold', color: '#374151', marginBottom: '6px' }}>
                      Key Features
                    </h4>
                    <ul style={{ paddingLeft: '18px', margin: 0, fontSize: '13px', color: '#4b5563', lineHeight: '1.6' }}>
                      {(Array.isArray(selectedProduct.features) 
                        ? selectedProduct.features 
                        : String(selectedProduct.features).split('\n')
                      )
                      .filter(feat => feat.trim() !== '')
                      .map((feature, idx) => (
                        <li key={idx}>{feature}</li>
                      ))}
                    </ul>
                  </div>
                )}

              </div>

            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default Products;
